    -- sets each "a.b.c" path in tbl (numbers in a path are list indexes: "x.color.1"); tables are copied
    apply = function (tbl, list, T)
        T = T or function (t) return t end
        local function copy(v)
            if type(v) ~= 'table' then return v end
            local o = T{}
            for k, x in pairs(v) do o[k] = copy(x) end
            return o
        end
        for path, v in pairs(list or {}) do
            local t, keys = tbl, {}
            for part in path:gmatch('[^%.]+') do keys[#keys + 1] = tonumber(part) or part end
            for i = 1, #keys - 1 do
                if type(t[keys[i]]) ~= 'table' then t[keys[i]] = T{} end
                t = t[keys[i]]
            end
            t[keys[#keys]] = copy(v)
        end
    end,
